fn reverse(a: &mut Vec<i32>) {
    let n = a.len();
    if n <= 1 {
        return;
    }

    let mut i: usize = 0;
    let mut j: usize = n - 1;

    while i < j {
        a.swap(i, j);
        i += 1;
        j -= 1;
    }
}